import { chromium } from '@playwright/test';
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { cpus, platform, release } from 'node:os';
import { execFileSync } from 'node:child_process';
import { relative, resolve } from 'node:path';
import { serveStyleBuild } from '../scripts/style-comparison.mjs';

const hash = (value) => createHash('sha256').update(value).digest('hex');
async function buildHash(dir) {
  const paths = (await readdir(dir, { recursive: true, withFileTypes: true })).filter((file) => file.isFile())
    .map((file) => `${file.parentPath}/${file.name}`).sort();
  const content = [];
  for (const path of paths) content.push([relative(resolve(dir), path).replaceAll('\\', '/'), hash(await readFile(path))]);
  return hash(JSON.stringify(content));
}
const versions = {};
const json = JSON.stringify({ sub: 'a'.repeat(5_000_000) });
const token = `eyJhbGciOiJIUzI1NiJ9.${Buffer.from(json).toString('base64url')}.c2ln`;
const browser = await chromium.launch();
try {
  for (const [version, dir] of Object.entries({ before: '.vite/jwt-review-before', after: 'dist' })) {
    const { server, url } = await serveStyleBuild(dir);
    try {
      const runs = [];
      for (let i = -1; i < 3; i++) {
        const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
        await page.goto(url + '#/jwt');
        const input = page.getByRole('textbox', { name: 'トークン', exact: true });
        await input.waitFor();
        await page.evaluate(() => {
          window.__measure = { last: performance.now(), maxFrameMs: 0, running: true };
          const frame = (now) => {
            const state = window.__measure;
            state.maxFrameMs = Math.max(state.maxFrameMs, now - state.last);
            state.last = now;
            if (state.running) requestAnimationFrame(frame);
          };
          requestAnimationFrame(frame);
        });
        await input.evaluate((element, value) => {
          window.__measure.start = performance.now();
          window.__measure.last = window.__measure.start;
          window.__measure.maxFrameMs = 0;
          const clipboardData = new DataTransfer();
          clipboardData.setData('text/plain', value);
          const event = new ClipboardEvent('paste', { bubbles: true, cancelable: true });
          Object.defineProperty(event, 'clipboardData', { value: clipboardData });
          element.dispatchEvent(event);
        }, token);
        await page.getByRole('region', { name: 'ペイロード', exact: true }).waitFor({ timeout: 30_000 });
        await page.evaluate(() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))));
        const run = await page.evaluate(() => {
          const state = window.__measure;
          state.running = false;
          return { elapsedMs: performance.now() - state.start, maxFrameMs: state.maxFrameMs,
            payloadShown: document.querySelector('pre[aria-label="ペイロード"]').textContent.length };
        });
        if (i >= 0) runs.push(run);
        await page.close();
      }
      versions[version] = { distSha256: await buildHash(dir), runs };
    } finally {
      server.closeAllConnections();
      await new Promise((resolve) => server.close(resolve));
    }
  }
  const sources = {};
  for (const path of ['src/tools/jwt-decoder/index.tsx', 'src/tools/jwt-decoder/calculation.ts', 'src/tools/jwt-decoder/diagnostics.ts']) sources[path] = hash(await readFile(path));
  const report = { measuredAt: new Date().toISOString(), head: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
    environment: { node: process.version, browser: browser.version(), platform: platform(), release: release(), cpu: cpus()[0].model },
    input: { subCharacters: 5_000_000, tokenUtf16: token.length, source: 'JSON.stringify({sub: "a".repeat(5000000)})をBase64URLにした合成JWT。署名検証はしない。' },
    scope: '変更前に退避したビルドと変更後の本番ビルド。各版で予備1回、測定3回。貼り付けからペイロード表示後の2描画まで。maxFrameMsはrequestAnimationFrameの最大間隔。時間には自動化とWorkerの待機・起動・転送・描画を含む。',
    sources, measurementSource: await readFile(new URL(import.meta.url), 'utf8'), versions };
  await writeFile('docs/records/jwt-worker-2026-11-21.json', JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify(versions));
} finally { await browser.close(); }
